pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {airdrop} from "../src/airdrop.sol";

contract InvMutTest is Test {
    airdrop c;
    function setUp() public { c = new airdrop(); }
    function testRegression_property() public {
        address token = address(new Token());
        address from = address(0x123);
        address to1 = address(0x456);
        address to2 = address(0x789);
        uint value = 100;
        vm.deal(from, 1 ether);
        vm.prank(from);
        address[] memory tos = new address[](2);
        tos[0] = to1;
        tos[1] = to2;
        bool success;
        try c.transfer(from, token, tos, value) returns (bool) {
            success = true;
        } catch {
            success = false;
        }
        assertEq(IToken(token).balanceOf(to1), value);
        assertEq(IToken(token).balanceOf(to2), value);
    }
}

interface IToken {
    function balanceOf(address) external view returns (uint256);
}

contract Token {
    mapping(address => uint256) public balanceOf;
    function transferFrom(address from, address to, uint256 amount) external returns (bool) {
        balanceOf[to] += amount;
        return true;
    }
}
